"""Pure requested motion for roundabout lane and pass-duration probes.

Requests are engineering controls. Original Native lane, speed and passing
observations must be measured independently from the executed actor state.
"""

from dataclasses import dataclass


OUTER_RIGHT_RADIUS_M = 14.5
INNER_LEFT_RADIUS_M = 11.5


@dataclass(frozen=True)
class SourceState:
    ego_speed_mps: float
    ego_radius_m: float
    follower_gap_arc_m: float
    slow_vehicle_ahead_arc_m: float | None
    slow_vehicle_speed_mps: float | None
    slow_vehicle_cleared: bool
    right_lane_center_radius_m: float = OUTER_RIGHT_RADIUS_M
    left_lane_center_radius_m: float = INNER_LEFT_RADIUS_M


@dataclass(frozen=True)
class Request:
    target_radius_m: float
    target_speed_mps: float
    phase: str
    pass_requested: bool


def request(case_suffix: str, state: SourceState) -> Request:
    """Compute a target from source state without asserting a legal outcome."""
    if state.ego_speed_mps < 0 or state.follower_gap_arc_m < 0:
        raise ValueError('Original ego or follower motion source invalid')
    if not 0 < state.left_lane_center_radius_m < state.right_lane_center_radius_m:
        raise ValueError('Original surveyed lane radii invalid')
    if case_suffix == 'probe_a':
        return Request(state.right_lane_center_radius_m, 3.0, 'right_lane_slow', False)
    if case_suffix == 'probe_b':
        return Request(state.left_lane_center_radius_m, 3.0, 'left_lane_slow', False)
    if case_suffix not in ('necessary_pass', 'post_pass_linger'):
        raise ValueError('Unknown exact roundabout case')
    if state.slow_vehicle_ahead_arc_m is None or state.slow_vehicle_speed_mps is None:
        raise ValueError('Pass case requires original slower-vehicle source')
    if state.slow_vehicle_speed_mps < 0:
        raise ValueError('Original slower-vehicle speed invalid')
    if not state.slow_vehicle_cleared:
        return Request(state.left_lane_center_radius_m, 4.0, 'pass_in_progress', True)
    if case_suffix == 'necessary_pass':
        return Request(state.right_lane_center_radius_m, 3.0, 'return_after_pass', False)
    return Request(state.left_lane_center_radius_m, 3.0, 'linger_after_pass', False)

"""Join original roundabout sources without deciding statutory impeding."""

import hashlib
import json
import math
from pathlib import Path

FRAMES = 600
RATE = 20


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def lines(path):
    path = Path(path)
    if not path.is_file():
        raise ValueError('Missing retained source: ' + path.name)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def polar(actor, center):
    return (math.hypot(actor['x_m'] - center[0], actor['y_m'] - center[1]),
            math.atan2(actor['y_m'] - center[1], actor['x_m'] - center[0]))


def lane(radius, geometry):
    outer = geometry['outer_right_lane_radius_m']
    inner = geometry['inner_left_lane_radius_m']
    if outer[0] <= radius < outer[1]:
        return 'extreme_right'
    if inner[0] <= radius < inner[1]:
        return 'inner_left'
    return 'outside_or_straddling'


def measure(config_path, native_path, frame_path, geometry_path):
    config = json.loads(Path(config_path).read_text())
    geometry = json.loads(Path(geometry_path).read_text())
    native, frames = lines(native_path), lines(frame_path)
    if config.get('frames') != FRAMES or config.get('rate_hz') != RATE or len(native) != FRAMES or len(frames) != FRAMES:
        raise ValueError('Exact 30-second source contract differs')
    if geometry.get('source_kind') not in ('synthetic_native_sample', 'original_native'):
        raise ValueError('Roundabout geometry provenance missing')
    outer, inner = geometry.get('outer_right_lane_radius_m'), geometry.get('inner_left_lane_radius_m')
    if (geometry.get('direction') != 'counterclockwise' or
            not isinstance(outer, list) or not isinstance(inner, list) or
            len(outer) != 2 or len(inner) != 2 or
            not 0 < inner[0] < inner[1] <= outer[0] < outer[1] or
            not geometry.get('same_direction_marked_lanes_source')):
        raise ValueError('Two marked same-direction roundabout lanes unverified')
    center = geometry.get('center_xy_m')
    if not isinstance(center, list) or len(center) != 2 or not all(isinstance(x, (int, float)) for x in center):
        raise ValueError('Roundabout center source missing')
    counts = {'extreme_right': 0, 'inner_left': 0, 'outside_or_straddling': 0,
              'follower_behind': 0, 'ego_slower_than_follower': 0,
              'slower_vehicle_ahead': 0, 'pass_in_progress': 0,
              'after_pass_right': 0, 'after_pass_left': 0}
    previous_frame = None
    first_clearance = None
    first_pass = None
    for i, (row, frame) in enumerate(zip(native, frames)):
        fid = row.get('native_frame')
        if type(fid) is not int or (previous_frame is not None and fid != previous_frame + 1):
            raise ValueError('Native frame sequence differs')
        previous_frame = fid
        t = i / RATE
        if (frame.get('native_frame') != fid or frame.get('video_frame') != i or
                any(not isinstance(x, (int, float)) or abs(x - t) > 1e-4 for x in (row.get('time_s'), frame.get('time_s')))):
            raise ValueError('Original Native/video frame-time join differs')
        if row.get('source_kind') != geometry['source_kind'] or set(row.get('actors', {})) < {'ego', 'follower'}:
            raise ValueError('Original ego/follower source missing')
        ego, follower = row['actors']['ego'], row['actors']['follower']
        if any(not isinstance(actor.get(key), (int, float)) or not math.isfinite(actor[key]) for actor in (ego, follower) for key in ('x_m', 'y_m', 'speed_mps')):
            raise ValueError('Original actor position or speed missing')
        if ego['speed_mps'] < 0 or follower['speed_mps'] < 0:
            raise ValueError('Original negative source speed')
        body = ego.get('body_vertices_native_m')
        if not isinstance(body, list) or len(body) < 4 or any(
                not isinstance(v, list) or len(v) < 2 for v in body):
            raise ValueError('Original ego body vertices missing')
        ego_radius, ego_angle = polar(ego, center)
        follow_radius, follow_angle = polar(follower, center)
        body_lanes = {lane(math.hypot(v[0]-center[0], v[1]-center[1]), geometry) for v in body}
        occupied = body_lanes.pop() if len(body_lanes) == 1 else 'outside_or_straddling'
        counts[occupied] += 1
        arc = (ego_angle - follow_angle) % (2 * math.pi)
        if 0 < arc < math.pi and abs(follow_radius - ego_radius) < 4.0:
            counts['follower_behind'] += 1
        if ego['speed_mps'] < follower['speed_mps']:
            counts['ego_slower_than_follower'] += 1
        pass_source = row.get('pass_observation')
        if pass_source is not None:
            if not isinstance(pass_source, dict) or not isinstance(pass_source.get('slower_vehicle_ahead'), bool) or not isinstance(pass_source.get('slower_vehicle_cleared'), bool):
                raise ValueError('Original pass observation incomplete')
            if pass_source['slower_vehicle_ahead']:
                counts['slower_vehicle_ahead'] += 1
            if pass_source['slower_vehicle_ahead'] and not pass_source['slower_vehicle_cleared'] and occupied == 'inner_left':
                counts['pass_in_progress'] += 1
                if first_pass is None:
                    first_pass = i
            if pass_source['slower_vehicle_cleared']:
                if first_clearance is None:
                    first_clearance = i
                counts['after_pass_right' if occupied == 'extreme_right' else 'after_pass_left'] += 1
    return {'format': 'c132924-source-roundabout-measurement-v1',
            'case_id': config['case_id'], 'frames': FRAMES, 'rate_hz': RATE,
            'counts': counts, 'first_pass_frame': first_pass,
            'first_clearance_frame': first_clearance,
            'source_hashes': {'config': sha(config_path), 'native': sha(native_path),
                              'frame_map': sha(frame_path), 'geometry': sha(geometry_path)},
            'impeding_judgment': None, 'passing_necessity_judgment': None,
            'physical_legal_verdict': None, 'original_pixels_verified': False}

"""Saved-only source analysis of roundabout lane and passing observations."""

import argparse
import hashlib
import json
from pathlib import Path

from capture import derive_channels
from measure import measure

SOURCES = ('native.jsonl','video_frames.jsonl','geometry.json')
VIDEOS = ('overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv')


def required(folder,name):
    path = Path(folder)/name
    if not path.is_file():
        raise ValueError('Missing required source: '+name)
    return path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def roundabout_lane_and_pass(folder,paths):
    return measure(Path(folder)/'config.json',*paths)


def impeding_source(facts):
    return {'follower_behind_frames':facts['counts']['follower_behind'],
            'ego_slower_frames':facts['counts']['ego_slower_than_follower'],
            'statutory_impeding_judgment':facts['impeding_judgment']}


def lane_occupancy_source(facts):
    return {key:facts['counts'][key] for key in
            ('extreme_right','inner_left','outside_or_straddling')}


def passing_source(facts):
    return {'slower_vehicle_ahead_frames':facts['counts']['slower_vehicle_ahead'],
            'pass_in_progress_frames':facts['counts']['pass_in_progress'],
            'necessity_judgment':facts['passing_necessity_judgment']}


def post_pass_source(facts):
    return {'first_clearance_frame':facts['first_clearance_frame'],
            'after_pass_right_frames':facts['counts']['after_pass_right'],
            'after_pass_left_frames':facts['counts']['after_pass_left']}


def analysis_report(folder):
    folder = Path(folder)
    config = json.loads(required(folder,'config.json').read_text())
    paths = [required(folder,name) for name in SOURCES]
    observed = roundabout_lane_and_pass(folder,paths)
    if observed['case_id'] != config['selected_case_id'] or observed['frames'] != 600:
        raise ValueError('Exact selected roundabout source differs')
    suffix = config['case_id'].rsplit('__',1)[-1]
    if suffix in ('necessary_pass','post_pass_linger') and observed['counts']['slower_vehicle_ahead']==0:
        raise ValueError('Original slower-vehicle pass source absent')
    functions = {'impeding_source':impeding_source,'lane_occupancy_source':lane_occupancy_source,
                 'passing_source':passing_source,'post_pass_source':post_pass_source}
    methods = ('impeding_source','lane_occupancy_source') if suffix in ('probe_a','probe_b') else (
        'impeding_source','passing_source','post_pass_source')
    return {'format':'worker-c132924-roundabout-analysis-v1',
            'case_id':config['selected_case_id'],'analysis_complete':True,
            'legal_verdict_claimed':False,
            'measurements':{method:{'method':method,'value':functions[method](observed),
                'sources':{name:sha(folder/name) for name in SOURCES}}
                for method in methods},
            'limitations':['Speed ordering and trailing position do not settle statutory impeding.',
                           'Controller requests do not establish pass necessity or lawful duration.',
                           'Original marked lane, body, slower-vehicle and pixel sources require independent review.']}


def finalize(attempt,output):
    from worker_exchange.native_output import physical_result,provenance_record,write_result
    attempt,output = Path(attempt).resolve(),Path(output).resolve()
    if output.exists() or (attempt/'result.json').exists():
        raise ValueError('Use fresh analysis path and retain original sources')
    config = json.loads(required(attempt,'config.json').read_text())
    if config.get('rate_hz') != 20 or config.get('duration_s') != 30:
        raise ValueError('Exact 600-frame source contract changed')
    report = analysis_report(attempt)
    facts = roundabout_lane_and_pass(attempt,[attempt/name for name in SOURCES])
    provenance = provenance_record(attempt)
    original = provenance['provenance_kind']=='native' and not provenance['diagnostic_fixture']
    result = {
        'case_id':config['selected_case_id'],'measured_values':facts,
        'target_checks':[{'target':'extreme-right lane during impeding, except necessary passing',
            'requested':config['selected_case_id'].rsplit('__',1)[-1],
            'measured':{'lane_counts':{key:facts['counts'][key] for key in
                ('extreme_right','inner_left','outside_or_straddling')},
                'first_pass_frame':facts['first_pass_frame'],
                'first_clearance_frame':facts['first_clearance_frame']},
            'method':'original frame-joined Native body, lane, follower and slower vehicle sources',
            'tolerance':'engineering source diagnostic only; statutory judgment pending',
            'matched':False,'physical_cause_confirmed':False,
            'cause_evidence':list(SOURCES)}],
        'setup_confirmed':False,'behavior_attempted':original,
        'maneuver_completed':False,
        'termination_reason':'independent physical and statutory source review pending',
        'physical_failure_flags':['marked_lane_and_body_review_pending',
                                  'impeding_and_passing_necessity_review_pending'],
        'trace_reference':'trace.jsonl','video_references':list(VIDEOS),
        'video_frame_map_reference':'video_frames.jsonl',
        'recording_description':config['recording_description'],
        'recording_evidence':derive_channels(attempt),
        'realized_observables':{'extreme_right_frames':{
            'value':facts['counts']['extreme_right'],'unit':'frames',
            'method':'source-joined Native body occupancy','time_window':'600 frames',
            'statistic':'count','reference':'native.jsonl'}},
        'accepted':False,'legal_verdict_claimed':False}
    result = physical_result(attempt,result)
    write_result(attempt,result)
    output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
    return report


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--attempt',required=True)
    parser.add_argument('--output',required=True)
    args=parser.parse_args()
    print(json.dumps(finalize(args.attempt,args.output)))
